importVerified(dataSetId: string, dataDirectory: string, anchor: GovernanceAnchor, projections: GovernanceProjection[], journalId: string): ProductionGovernanceJournal {
  this.assertHeld()
  if (this.registry.entries.some((entry) => entry.dataSetId === dataSetId)) throw Error('GOVERNANCE_IMPORT_ALREADY_KNOWN')
  const locatorPath = join(this.configurationDirectory, 'location.json')
  if (existsSync(locatorPath)) {
    const locator = JSON.parse(readMetadata(locatorPath).toString('utf8'))
    if (locator.dataSetId === dataSetId) throw Error('GOVERNANCE_KNOWN_LOCATOR_REQUIRES_LEDGER')
  }
  const markerPath = join(canonicalProductionDirectory(dataDirectory), '.mashiro-governance.json')
  if (existsSync(markerPath)) {
    const marker = markerSchema.parse(JSON.parse(readMetadata(markerPath).toString('utf8')))
    if (marker.dataSetId !== dataSetId || marker.journalId !== journalId) throw Error('GOVERNANCE_IMPORT_MARKER_MISMATCH')
  }
  const entry: Registry['entries'][number] = { dataSetId, state: 'PREPARING', journalId, anchor }
  this.registry.entries.push(entry); this.persist()
  const journal = ProductionGovernanceJournal.create(this.directory, dataSetId, anchor, projections, journalId)
  entry.state = 'READY'; this.persist(); this.stamp(dataDirectory, journal)
  return journal
}
